// ========================== Service ==========================
type AIService interface {
	// 核心：接收聊天消息，AI 异步处理后以 Bot 身份回写群聊
	ProcessMessage(ctx context.Context, req *ProcessMessageReq) (r *ProcessMessageResp, err error)
	// Bot CRUD
	CreateBot(ctx context.Context, req *CreateBotReq) (r *CreateBotResp, err error)

	UpdateBot(ctx context.Context, req *UpdateBotReq) (r *UpdateBotResp, err error)

	ListBots(ctx context.Context, req *ListBotsReq) (r *ListBotsResp, err error)

	GetBot(ctx context.Context, req *GetBotReq) (r *GetBotResp, err error)

	DeleteBot(ctx context.Context, req *DeleteBotReq) (r *DeleteBotResp, err error)
	// Bot-群绑定
	AddBotToGroup(ctx context.Context, req *AddBotToGroupReq) (r *AddBotToGroupResp, err error)

	RemoveBotFromGroup(ctx context.Context, req *RemoveBotFromGroupReq) (r *RemoveBotFromGroupResp, err error)

	ListGroupBots(ctx context.Context, req *ListGroupBotsReq) (r *ListGroupBotsResp, err error)

	ListBotGroups(ctx context.Context, req *ListBotGroupsReq) (r *ListBotGroupsResp, err error)
	// MCP Server / Tool 管理
	RegisterMCPServer(ctx context.Context, req *RegisterMCPServerReq) (r *RegisterMCPServerResp, err error)

	RefreshMCPServer(ctx context.Context, req *RefreshMCPServerReq) (r *RefreshMCPServerResp, err error)

	ListMCPServers(ctx context.Context, req *ListMCPServersReq) (r *ListMCPServersResp, err error)

	DeleteMCPServer(ctx context.Context, req *DeleteMCPServerReq) (r *DeleteMCPServerResp, err error)

	ListTools(ctx context.Context, req *ListToolsReq) (r *ListToolsResp, err error)
	// 用户凭证
	SaveCredential(ctx context.Context, req *SaveCredentialReq) (r *SaveCredentialResp, err error)

	DeleteCredential(ctx context.Context, req *DeleteCredentialReq) (r *DeleteCredentialResp, err error)

	ListCredentials(ctx context.Context, req *ListCredentialsReq) (r *ListCredentialsResp, err error)
}

