func NewAIServiceProcessor(handler AIService) *AIServiceProcessor {
	self := &AIServiceProcessor{handler: handler, processorMap: make(map[string]thrift.TProcessorFunction)}
	self.AddToProcessorMap("ProcessMessage", &aIServiceProcessorProcessMessage{handler: handler})
	self.AddToProcessorMap("CreateBot", &aIServiceProcessorCreateBot{handler: handler})
	self.AddToProcessorMap("UpdateBot", &aIServiceProcessorUpdateBot{handler: handler})
	self.AddToProcessorMap("ListBots", &aIServiceProcessorListBots{handler: handler})
	self.AddToProcessorMap("GetBot", &aIServiceProcessorGetBot{handler: handler})
	self.AddToProcessorMap("DeleteBot", &aIServiceProcessorDeleteBot{handler: handler})
	self.AddToProcessorMap("AddBotToGroup", &aIServiceProcessorAddBotToGroup{handler: handler})
	self.AddToProcessorMap("RemoveBotFromGroup", &aIServiceProcessorRemoveBotFromGroup{handler: handler})
	self.AddToProcessorMap("ListGroupBots", &aIServiceProcessorListGroupBots{handler: handler})
	self.AddToProcessorMap("ListBotGroups", &aIServiceProcessorListBotGroups{handler: handler})
	self.AddToProcessorMap("RegisterMCPServer", &aIServiceProcessorRegisterMCPServer{handler: handler})
	self.AddToProcessorMap("RefreshMCPServer", &aIServiceProcessorRefreshMCPServer{handler: handler})
	self.AddToProcessorMap("ListMCPServers", &aIServiceProcessorListMCPServers{handler: handler})
	self.AddToProcessorMap("DeleteMCPServer", &aIServiceProcessorDeleteMCPServer{handler: handler})
	self.AddToProcessorMap("ListTools", &aIServiceProcessorListTools{handler: handler})
	self.AddToProcessorMap("SaveCredential", &aIServiceProcessorSaveCredential{handler: handler})
	self.AddToProcessorMap("DeleteCredential", &aIServiceProcessorDeleteCredential{handler: handler})
	self.AddToProcessorMap("ListCredentials", &aIServiceProcessorListCredentials{handler: handler})
	return self
}
func (p *AIServiceProcessor) Process(ctx context.Context, iprot, oprot thrift.TProtocol) (success bool, err thrift.TException) {
	name, _, seqId, err := iprot.ReadMessageBegin()
	if err != nil {
		return false, err
	}
	if processor, ok := p.GetProcessorFunction(name); ok {
		return processor.Process(ctx, seqId, iprot, oprot)
	}
	iprot.Skip(thrift.STRUCT)
	iprot.ReadMessageEnd()
	x := thrift.NewTApplicationException(thrift.UNKNOWN_METHOD, "Unknown function "+name)
	oprot.WriteMessageBegin(name, thrift.EXCEPTION, seqId)
	x.Write(oprot)
	oprot.WriteMessageEnd()
	oprot.Flush(ctx)
	return false, x
}

